def default_retry_schedule(num_retries: int) -> list[float]:
    """Exponential backoff delays, matching the Rust client's defaults."""
    schedule: list[float] = []
    backoff = 0.5
    for _ in range(num_retries):
        schedule.append(backoff)
        backoff = min(_MAX_BACKOFF, backoff * 2)
    return schedule


